CREATE TABLE "public"."note" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "created_at" timestamp with time zone DEFAULT now(),
    "category_id" bigint NOT NULL,
    "body" text NOT NULL,
    "author" bigint
);

ALTER TABLE "public"."note" ENABLE ROW LEVEL SECURITY;

CREATE UNIQUE INDEX note_pkey ON public.note USING btree (id);

ALTER TABLE "public"."note"
    ADD CONSTRAINT "note_pkey" PRIMARY KEY USING INDEX "note_pkey";

ALTER TABLE "public"."note"
    ADD CONSTRAINT "note_author_fkey" FOREIGN KEY (author) REFERENCES "user" (id) ON DELETE SET NULL NOT valid;

ALTER TABLE "public"."note" validate CONSTRAINT "note_author_fkey";

ALTER TABLE "public"."note"
    ADD CONSTRAINT "note_category_id_fkey" FOREIGN KEY (category_id) REFERENCES category (id) NOT valid;

ALTER TABLE "public"."note" validate CONSTRAINT "note_category_id_fkey";

SET check_function_bodies = OFF;

CREATE OR REPLACE FUNCTION public.get_user_id ()
    RETURNS bigint
    LANGUAGE sql
    SECURITY DEFINER
    AS $function$
    SELECT
        user_id
    FROM
        "public"."account"
    WHERE
        auth_user_id = auth.uid ()
    LIMIT 1;
$function$;

CREATE POLICY "Users can edit notes in their categories" ON "public"."note" AS permissive
    FOR ALL TO authenticated
        USING ((category_id IN (
            SELECT
                category.id
            FROM
                category
            WHERE (category.user_id = get_user_id ()))));

ALTER VIEW gap SET ( security_invoker = TRUE);
ALTER VIEW gap_monthly SET ( security_invoker = TRUE);
ALTER VIEW gap_daily SET ( security_invoker = TRUE);
ALTER VIEW insight SET ( security_invoker = TRUE);
ALTER VIEW insight_weekly SET ( security_invoker = TRUE);
ALTER VIEW "public"."invitation_admin" SET ( security_invoker = FALSE);
ALTER VIEW "public"."event_x" SET ( security_invoker = TRUE);
ALTER VIEW "public"."waitlist_admin" SET ( security_invoker = FALSE);
ALTER VIEW "public"."sync_admin" SET ( security_invoker = FALSE);
